/**
 * `nx run contracts:generate`: writes the JSON Schema of every registry entry
 * (and of every option of a union) to `generated/json-schema/<name>.schema.json`,
 * then its Go type to `apps/runner/internal/contracts/<name>.go` with
 * go-jsonschema, and the Go type of each union to `<name>.go`. Deterministic:
 * sorted keys, stable file order, stale generated files removed. The output
 * is committed; CI fails when running it leaves a diff. It also writes every
 * Contrat (ADR 0005) to `apps/runner/internal/contrat/contrats/<id>.v<version>.json`,
 * which the Runner embeds, and the example Contrat beside its fixtures,
 * and each case of the canvas's rules to `fixtures/process/<case>.json`.
 */
import { execFileSync } from 'node:child_process';
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { z } from 'zod';
import { exampleContrat } from '../fixtures/contrats/example.js';
import { type ProcessCase, PROCESS_CASES } from '../fixtures/process/cases.js';
import { type Contrat, CONTRATS } from './contrats/index.js';
import { generatedEntries, goConstants, type GoUnion, goUnions } from './registry.js';

const GO_JSONSCHEMA = 'github.com/atombender/go-jsonschema@v0.24.1';
const GO_HEADER = '// Code generated by github.com/atombender/go-jsonschema, DO NOT EDIT.';
const CONSTANTS_FILE = 'constants.go';
const CONSTANTS_HEADER = '// Code generated by nx run contracts:generate, DO NOT EDIT.';

const packageRoot = resolve(import.meta.dirname, '..');
const jsonSchemaDir = join(packageRoot, 'generated', 'json-schema');
const runnerRoot = resolve(packageRoot, '../../apps/runner');
const goDir = join(runnerRoot, 'internal', 'contracts');
const runnerContratsDir = join(runnerRoot, 'internal', 'contrat', 'contrats');
const exampleContratFile = join(packageRoot, 'fixtures', 'contrats', 'example.json');
const processCasesDir = join(packageRoot, 'fixtures', 'process');

/**
 * The Contrats the Runner embeds: the current version of each Étape's, and the
 * example one, which `crewdeck-runner contrat check example` and the tests use
 * (no Étape has it). Past versions stay in TypeScript, for their labels.
 */
export const embeddedContrats: readonly Contrat[] = [...CONTRATS, exampleContrat];

export const contratFileName = (contrat: Contrat): string => `${contrat.id}.v${contrat.version}.json`;

/** A Contrat as the Runner reads it: the declaration, in its own order (the rules' order is the check's). */
export const renderContrat = (contrat: Contrat): string => `${JSON.stringify(contrat, null, 2)}\n`;

export const processCaseFileName = (processCase: ProcessCase): string => `${processCase.name}.json`;

/** A case of the canvas's rules as the page's and the server's tests read it. */
export const renderProcessCase = ({ change, definition, sources, refusals, gaps }: ProcessCase): string =>
  `${JSON.stringify({ change, definition, sources, refusals, gaps }, null, 2)}\n`;

export interface RegistryEntry {
  name: string;
  schema: z.ZodType;
}

/** `agent-session` → `AgentSession`: the title, hence the Go type's name. */
const typeName = (name: string): string =>
  name
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');

const sortKeys = (value: unknown, key?: string): unknown => {
  if (Array.isArray(value)) {
    const items = value.map((item) => sortKeys(item));
    return key === 'required' ? items.sort() : items;
  }
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value)
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
        .map(([k, v]) => [k, sortKeys(v, k)]),
    );
  }
  return value;
};

export const renderJsonSchema = ({ name, schema }: RegistryEntry): string => {
  const jsonSchema = { ...z.toJSONSchema(schema, { target: 'draft-2020-12' }), title: typeName(name) };
  return `${JSON.stringify(sortKeys(jsonSchema), null, 2)}\n`;
};

/** The Go file of `constants`, one constant each, in the order of their names, as gofmt aligns them. */
export const renderGoConstants = (constants: Readonly<Record<string, number>>): string => {
  const names = Object.keys(constants).sort();
  const width = Math.max(...names.map((name) => name.length));
  const lines = names.map((name) => `\t${name.padEnd(width)} = ${constants[name]}`);
  return `${CONSTANTS_HEADER}\n\npackage contracts\n\n// The constants of packages/contracts the Runner shares with the server.\nconst (\n${lines.join('\n')}\n)\n`;
};

/**
 * The Go type of a discriminated union, which go-jsonschema cannot write: a
 * struct with one pointer per option (exactly one set), the constants of the
 * discriminator, and the JSON methods that read the option the discriminator
 * names and write the one that is set, its discriminator filled in. Written
 * as gofmt formats it.
 */
export const renderGoUnion = ({ name, discriminator, options }: GoUnion): string => {
  const type = typeName(name);
  const sorted = [...options].sort((a, b) => (typeName(a.value) < typeName(b.value) ? -1 : 1));
  const fields = sorted.map((option) => ({ field: typeName(option.value), option: `${type}${typeName(option.value)}`, value: option.value }));
  const kind = (field: string): string => `${type}${typeName(discriminator)}${field}`;
  const fieldWidth = Math.max(...fields.map(({ field }) => field.length));
  const kindWidth = Math.max(...fields.map(({ field }) => kind(field).length));
  const goField = typeName(discriminator);
  const lines = [
    CONSTANTS_HEADER,
    '',
    'package contracts',
    '',
    'import (',
    '\t"encoding/json"',
    '\t"fmt"',
    ')',
    '',
    `// ${type} is one of the types below, told apart by "${discriminator}": exactly one field is set.`,
    `type ${type} struct {`,
    ...fields.map(({ field, option }) => `\t${field.padEnd(fieldWidth)} *${option}`),
    '}',
    '',
    `// The values of "${discriminator}" in ${type}.`,
    'const (',
    ...fields.map(({ field, value }) => `\t${kind(field).padEnd(kindWidth)} = ${JSON.stringify(value)}`),
    ')',
    '',
    `// ${goField} is the "${discriminator}" of the type set, "" when none is.`,
    `func (u ${type}) ${goField}() string {`,
    '\tswitch {',
    ...fields.flatMap(({ field }) => [`\tcase u.${field} != nil:`, `\t\treturn ${kind(field)}`]),
    '\t}',
    '\treturn ""',
    '}',
    '',
    '// Value is the type set, as a pointer, nil when none is.',
    `func (u ${type}) Value() any {`,
    '\tswitch {',
    ...fields.flatMap(({ field }) => [`\tcase u.${field} != nil:`, `\t\treturn u.${field}`]),
    '\t}',
    '\treturn nil',
    '}',
    '',
    `// MarshalJSON implements json.Marshaler: the type set, its "${discriminator}" filled in.`,
    `func (u ${type}) MarshalJSON() ([]byte, error) {`,
    '\tswitch {',
    ...fields.flatMap(({ field }) => [
      `\tcase u.${field} != nil:`,
      `\t\tv := *u.${field}`,
      `\t\tv.${goField} = ${kind(field)}`,
      '\t\treturn json.Marshal(v)',
    ]),
    '\t}',
    `\treturn nil, fmt.Errorf("${type}: no type set")`,
    '}',
    '',
    `// UnmarshalJSON implements json.Unmarshaler: the type its "${discriminator}" names, checked by its own UnmarshalJSON.`,
    `func (u *${type}) UnmarshalJSON(data []byte) error {`,
    '\tvar head struct {',
    `\t\t${goField} string \`json:"${discriminator}"\``,
    '\t}',
    '\tif err := json.Unmarshal(data, &head); err != nil {',
    '\t\treturn err',
    '\t}',
    `\t*u = ${type}{}`,
    `\tswitch head.${goField} {`,
    ...fields.flatMap(({ field, option }) => [
      `\tcase ${kind(field)}:`,
      `\t\tu.${field} = new(${option})`,
      `\t\treturn json.Unmarshal(data, u.${field})`,
    ]),
    '\t}',
    `\treturn fmt.Errorf("${type}: unknown ${discriminator} %q", head.${goField})`,
    '}',
    '',
  ];
  return lines.join('\n');
};

const removeStale = (dir: string, keep: Set<string>, isGenerated: (file: string) => boolean): void => {
  for (const file of readdirSync(dir)) {
    if (!keep.has(file) && isGenerated(file)) rmSync(join(dir, file));
  }
};

const generate = (): void => {
  const entries = [...generatedEntries].sort((a, b) => (a.name < b.name ? -1 : 1));
  mkdirSync(jsonSchemaDir, { recursive: true });
  mkdirSync(goDir, { recursive: true });

  for (const entry of entries) {
    const schemaFile = join(jsonSchemaDir, `${entry.name}.schema.json`);
    writeFileSync(schemaFile, renderJsonSchema(entry));
    execFileSync(
      'go',
      ['run', GO_JSONSCHEMA, '--package', 'contracts', '--tags', 'json', '--struct-name-from-title', '--output', join(goDir, `${entry.name}.go`), schemaFile],
      { cwd: runnerRoot, stdio: 'inherit' },
    );
  }

  writeFileSync(join(goDir, CONSTANTS_FILE), renderGoConstants(goConstants));
  for (const union of goUnions) writeFileSync(join(goDir, `${union.name}.go`), renderGoUnion(union));

  removeStale(jsonSchemaDir, new Set(entries.map((e) => `${e.name}.schema.json`)), (file) => file.endsWith('.schema.json'));
  removeStale(
    goDir,
    new Set([...entries.map((e) => `${e.name}.go`), ...goUnions.map((union) => `${union.name}.go`), CONSTANTS_FILE]),
    (file) => {
      if (!file.endsWith('.go') || file.endsWith('_test.go')) return false;
      const text = readFileSync(join(goDir, file), 'utf8');
      return text.startsWith(GO_HEADER) || text.startsWith(CONSTANTS_HEADER);
    },
  );
  execFileSync('gofmt', ['-w', goDir], { stdio: 'inherit' });

  mkdirSync(runnerContratsDir, { recursive: true });
  for (const contrat of embeddedContrats) writeFileSync(join(runnerContratsDir, contratFileName(contrat)), renderContrat(contrat));
  removeStale(runnerContratsDir, new Set(embeddedContrats.map(contratFileName)), (file) => file.endsWith('.json'));
  writeFileSync(exampleContratFile, renderContrat(exampleContrat));

  for (const processCase of PROCESS_CASES) writeFileSync(join(processCasesDir, processCaseFileName(processCase)), renderProcessCase(processCase));
  removeStale(processCasesDir, new Set(PROCESS_CASES.map(processCaseFileName)), (file) => file.endsWith('.json'));
};

if (import.meta.main) generate();
